package com.resolvenow.complaint;
import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ComplaintService { private static final Logger log=LoggerFactory.getLogger(ComplaintService.class); private final ComplaintRepository repository; private final AssignmentClient assignmentClient; private final NotificationClient notificationClient;
 public ComplaintService(ComplaintRepository repository,AssignmentClient assignmentClient,NotificationClient notificationClient){this.repository=repository;this.assignmentClient=assignmentClient;this.notificationClient=notificationClient;}
 public List<Complaint> all(){return repository.findAll();} public Complaint one(Long id){return repository.findById(id).orElseThrow();}
 public Complaint create(Complaint complaint){Complaint saved=repository.save(complaint); AssignmentClient.AssignmentRequest request=new AssignmentClient.AssignmentRequest(saved.getId(),saved.getCustomerEmail()); RuntimeException failure=null; for(int attempt=1;attempt<=3;attempt++){try{assignmentClient.assign(request); failure=null; break;}catch(RuntimeException exception){failure=exception;}} if(failure!=null)log.warn("Unable to assign complaint after retries {}",saved.getId(),failure); return saved;}
 public Complaint updateStatus(Long id,Complaint.Status status){Complaint complaint=one(id);complaint.setStatus(status);Complaint saved=repository.save(complaint); NotificationClient.NotificationRequest request=new NotificationClient.NotificationRequest(saved.getId(),saved.getCustomerEmail(),"Complaint status changed to "+saved.getStatus()); RuntimeException failure=null; for(int attempt=1;attempt<=3;attempt++){try{notificationClient.notify(request); failure=null; break;}catch(RuntimeException exception){failure=exception;}} if(failure!=null)log.warn("Unable to notify customer after retries for complaint {}",saved.getId(),failure); return saved;} public void delete(Long id){repository.deleteById(id);}
}
